import sys

def repeatedRows(matrix):
    seen = set()
    result = []
    for i, row in enumerate(matrix):
        row_tuple = tuple(row)
        if row_tuple in seen:
            result.append(i)
        else:
            seen.add(row_tuple)
    return result

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        R = int(next(iterator))
        C = int(next(iterator))
    except StopIteration:
        return

    matrix = []
    for _ in range(R):
        row = []
        for _ in range(C):
            row.append(int(next(iterator)))
        matrix.append(row)

    result = repeatedRows(matrix)
    print(*(result))

if __name__ == "__main__":
    main()
